}
function lerp(a, b, t) { return a + (b - a) * t; }
function smooth(t) { return t * t * (3 - 2 * t); }

var running = false;
var phase = 0;
var lastFrame = 0;

function updateParticles(p) {
  naParticles.forEach(function (pt) {
    var t = smooth((p + pt.off) % 1);
    place(pt.g, lerp(pt.s[0], pt.e[0], t), lerp(pt.s[1], pt.e[1], t));
    pt.g.opacity(0.22 + 0.78 * (1 - Math.abs(t - 0.55) * 1.3));
  });
  clParticles.forEach(function (pt) {
    var t = smooth((p * 1.1 + pt.off) % 1);
    place(pt.g, lerp(pt.s[0], pt.e[0], t), lerp(pt.s[1], pt.e[1], t));
    pt.g.opacity(0.25 + 0.75 * (1 - Math.abs(t - 0.5) * 1.25));
  });
  bubbles.forEach(function (pt) {
    var t = (p * 1.25 + pt.off) % 1;
    var y = lerp(304, 118, t);
