    pt.g.opacity(0.2 + 0.8 * (1 - t));
  });
  drops.forEach(function (pt) {
    var t = (p * 0.95 + pt.off) % 1;
    var x, y;
    if (t < 0.48) {
      x = lerp(350, 458, t / 0.48);
      y = lerp(330, 262, t / 0.48);
    } else {
      x = lerp(458, 502, (t - 0.48) / 0.52);
      y = lerp(262, 374, (t - 0.48) / 0.52);
    }
    pt.g.center(x, y);
    pt.g.opacity(0.22 + 0.78 * Math.sin(Math.PI * t));
  });
}
function frame(ts) {
  if (!running) {
    lastFrame = 0;
    return;
  }
  if (!lastFrame) lastFrame = ts;
  phase += (ts - lastFrame) / 2600;
  lastFrame = ts;
  updateParticles(phase);
  requestAnimationFrame(frame);
}
function setRunning(on) {
  running = on;
  var btn = document.getElementById('electrolysisAnimationInput');
  if (btn) {
    btn.textContent = on ? 'Pause electrolysis' : 'Run electrolysis';
    btn.classList.toggle('active', on);
  }
  if (on) requestAnimationFrame(frame);
}
function trigger_electrolysisAnimation() {
  setRunning(!running);
}
updateParticles(0.12);

