}
function showAnodeReaction() {
  anodeHL.show();
  cathodeHL.hide();
  anodeCallout.show();
  cathodeCallout.hide();
  showPopup('Anode oxidation', 'At the anode, chloride ions lose electrons: 2Cl⁻ → Cl₂(g) + 2e⁻. The chlorine gas rises into the central collector instead of mixing with liquid sodium.');
}

var cathodeHit = apparatus.rect(285, 138).fill({ color: '#fff', opacity: 0 }).move(158, 292);
cathodeHit.css('cursor', 'pointer')
