/* guided demo steps */
var demoSteps = [
  {
    title: 'Identify the cell layout',
    narration: 'The Downs cell contains molten NaCl rather than water, with a central anode, an outer cathode region, and an iron screen separating the two product zones.'
  },
  {
    title: 'Follow ion migration',
    narration: 'When the animation runs, Cl⁻ ions migrate toward the central anode while Na⁺ ions migrate toward the cathode compartment. This microscopic motion drives the macroscopic production of chlorine and sodium.'
  },
  {
    title: 'Click the electrodes',
    narration: 'Click the cathode to see Na⁺ + e⁻ → Na(l), then click the anode to see 2Cl⁻ → Cl₂(g) + 2e⁻. The signs determine which ion is reduced and which is oxidized.'
  },
  {
    title: 'Separate the products',
    narration: 'Chlorine gas rises through the central collector and exits through the Cl₂ outlet, while liquid sodium collects in the side reservoir and drains through the Na outlet. The iron screen prevents recombination.'
  }
];
var currentStep = 0;

function applyStep() {
  var step = demoSteps[currentStep];
  document.getElementById('demoNarration').textContent = step.narration;
  document.getElementById('stepLabel').textContent = (currentStep + 1) + '/' + demoSteps.length + ' ' + step.title;

  cathodeHL.hide();
  anodeHL.hide();
  separatorHL.hide();
  cathodeCallout.hide();
  anodeCallout.hide();
  overallCallout.hide();

  if (currentStep === 0) {
    setRunning(false);
  } else if (currentStep === 1) {
    setRunning(true);
  } else if (currentStep === 2) {
    setRunning(true);
    cathodeHL.show();
    anodeHL.show();
  } else if (currentStep === 3) {
    setRunning(true);
    separatorHL.show();
    overallCallout.show();
  }
}
function nextStep() {
  currentStep = (currentStep + 1) % demoSteps.length;
  applyStep();
}
function prevStep() {
  currentStep = (currentStep + demoSteps.length - 1) % demoSteps.length;
  applyStep();
}

applyStep();
window.__markRendered();
