    place(pt.g, lerp(pt.s[0], pt.e[0], t), lerp(pt.s[1], pt.e[1], t));
    pt.g.opacity(0.2 + 0.8 * (1 - Math.min(1, Math.abs(t - 0.5) * 1.25)));
  });
  bubbles.forEach(function (pt) {
    var t = (p * 1.2 + pt.off) % 1;
    var y = lerp(357, 150, t);
    pt.g.center(pt.x + Math.sin(t * 6.28) * 4, y);
    pt.g.opacity(0.15 + 0.75 * (1 - t));
  });
  drops.forEach(function (pt) {
    var t = (p * 0.95 + pt.off) % 1;
    var x, y;
    if (t < 0.45) {
      x = lerp(400, 494, t / 0.45);
      y = lerp(334, 268, t / 0.45);
    } else {
      x = lerp(494, 530, (t - 0.45) / 0.55);
      y = lerp(268, 382, (t - 0.45) / 0.55);
    }
    pt.g.center(x, y);
    pt.g.opacity(0.15 + 0.75 * Math.sin(Math.PI * t));
  });
}
