/* animation control */
var running = false;
var phase = 0;
var lastFrame = 0;
function frame(ts) {
  if (!running) {
    lastFrame = 0;
    return;
  }
  if (!lastFrame) lastFrame = ts;
  phase += (ts - lastFrame) / 2600;
  lastFrame = ts;
  updateParticles(phase);
  requestAnimationFrame(frame);
}
function setRunning(on) {
  running = on;
  var btn = document.getElementById('electrolysisAnimationInput');
  if (btn) {
    btn.textContent = on ? 'Pause electrolysis' : 'Run electrolysis';
    btn.classList.toggle('active', on);
  }
  if (on) {
    motionLayer.show();
    requestAnimationFrame(frame);
  } else {
    motionLayer.hide();
  }
}
function trigger_electrolysisAnimation() {
  setRunning(!running);
}

