    setRunning(true);
    separatorHL.show();
    overallCallout.show();
  }
}
function nextStep() {
  currentStep = (currentStep + 1) % demoSteps.length;
  applyStep();
}
function prevStep() {
  currentStep = (currentStep + demoSteps.length - 1) % demoSteps.length;
  applyStep();
